oxy_webhelp_navlinks = {"tocId-d39536e59042":{"topics":[{"title":"Dynamic disk foreign state after domain controller recovery","shortdesc":"<p class=\"shortdesc\">During a system state recovery of a domain controller to a new virtual machine, the         status of dynamic disks appear as Foreign on the new virtual machine.<\/p>","href":"adds\/dynamic_disk_foreign_state_dc.html","attributes":{"data-id":"dynamic_disk_foreign_state_dc"},"menu":{"hasChildren":false},"tocID":"dynamic_disk_foreign_state_dc-d39536e59043","next":"dynamic_disk_foreign_state_dc-d39536e59043"},{"title":"DNS debug log file path not restored","shortdesc":"<p class=\"shortdesc\">During system state recovery of a domain controller with DNS debug logging enabled,         the custom log file path may not be valid on the recovery target, causing DNS debug logging         to revert to the default path or the DNS Service to fail if the path is         inaccessible.<\/p>","href":"adds\/dns_debug_log_path_not_restored.html","attributes":{"data-id":"dns_debug_log_path_not_restored"},"menu":{"hasChildren":false},"tocID":"dns_debug_log_path_not_restored-d39536e59065","next":"dns_debug_log_path_not_restored-d39536e59065"},{"title":"Failed AD forest health checks","shortdesc":"<p class=\"shortdesc\">After an Active Directory forest recovery completes, health checks validate the state         of the recovered environment. In some cases, one or more health checks may fail, causing the         recovery to finish with a <samp class=\"ph msgph\">Incomplete due to warnings<\/samp> status.<\/p>","href":"adds\/ad_failed_health_checks.html","attributes":{"data-id":"ad_failed_health_checks"},"menu":{"hasChildren":false},"tocID":"ad_failed_health_checks-d39536e59087","next":"ad_failed_health_checks-d39536e59087"}]}};